function initialLocale() { const query = new URLSearchParams(location.search).get('lang'); if (query === 'en' || query === 'zh') return query; try { return localStorage.getItem('studygps-locale') === 'en' ? 'en' : 'zh'; } catch (_) { return 'zh'; } }
function t(key, values) { let value = COPY[locale][key] || COPY.en[key] || key; for (const [name, replacement] of Object.entries(values || {})) value = value.replaceAll('{' + name + '}', String(replacement)); return value; }
function el(tag, className, text) { const item = document.createElement(tag); if (className) item.className = className; if (text !== undefined && text !== null) item.textContent = String(text); return item; }
function append(parent, ...children) { for (const child of children.flat()) if (child) parent.append(child); return parent; }
function button(text, className, callback) { const item = el('button', className || 'button button-dark', text); item.type = 'button'; if (callback) item.addEventListener('click', callback); return item; }
function formButton(text) { const item = button(text, 'button button-dark'); item.type = 'submit'; return item; }
function number(value, fallback = '—') { return typeof value === 'number' && Number.isFinite(value) ? new Intl.NumberFormat(locale === 'zh' ? 'zh-CN' : 'en-AU', {maximumFractionDigits:1}).format(value) : fallback; }
function date(value) { if (!value || !Number.isFinite(Date.parse(value))) return t('noDate'); const timeZone = data?.user?.timezone || 'Australia/Sydney'; const opts = {month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone}; try { return new Intl.DateTimeFormat(locale === 'zh' ? 'zh-CN' : 'en-AU', opts).format(new Date(value)); } catch (_) { delete opts.timeZone; return new Intl.DateTimeFormat(locale === 'zh' ? 'zh-CN' : 'en-AU', opts).format(new Date(value)); } }
