function applyLocale() { document.documentElement.lang = locale === 'zh' ? 'zh-CN' : 'en'; document.title = 'StudyGPS · ' + t('workspace'); document.querySelectorAll('[data-i18n]').forEach(node => {node.textContent = t(node.dataset.i18n);}); document.querySelectorAll('[data-i18n-aria]').forEach(node => node.setAttribute('aria-label',t(node.dataset.i18nAria))); document.querySelectorAll('[data-locale]').forEach(node => node.setAttribute('aria-pressed', String(node.dataset.locale === locale))); for (const [id,path] of [['workspace-link','/portal.html'],['demo-link','/demo.html'],['home-link','/'],['auth-demo-link','/demo.html']]) $(id).href = path + '?lang=' + locale; if ($('auth-environment')) { $('auth-environment').textContent = t('development'); $('auth-environment').hidden = !development; } if (data) $('role-label').textContent = t(data.user.role === 'teacher' ? 'teacher' : 'student'); }
function inputField(name, label, options = {}) { const container = el('div','field'); const caption = el('label',null,label); caption.htmlFor = name; const input = el(options.multiline ? 'textarea' : options.select ? 'select' : 'input'); input.id = name; input.name = name; if (!options.multiline && !options.select) input.type = options.type || 'text'; for (const attr of ['min','max','step','maxLength','minLength','rows','placeholder','autocomplete']) if (options[attr] !== undefined) input[attr] = options[attr]; if (options.required) input.required = true; if (options.inputMode) input.inputMode = options.inputMode; if (options.select) for (const option of options.select) { const node = el('option',null,option.label); node.value = option.value; input.append(node); } input.value = options.value ?? ''; append(container,caption,input); if (options.hint) { const hint = el('span','hint',options.hint); hint.id = name + '-hint'; input.setAttribute('aria-describedby',hint.id); container.append(hint); } return {container,input}; }
function panel(title, index, icon) { const node = el('section','panel'); const head = el('div','panel-heading'); const text = el('div'); if (index) text.append(el('span','section-index',index)); text.append(el('h2',null,title)); append(head,text,icon ? el('span','icon',icon) : null); node.append(head); return node; }
function empty(title, text, symbol = '↗') { return append(el('div','empty-state'),el('span',null,symbol),el('h3',null,title),text ? el('p',null,text) : null); }
function loading(title) { const node = el('div','detail-loading'); node.setAttribute('role','status'); node.setAttribute('aria-live','polite'); append(node,el('div','loading-line'),el('div','loading-line'),el('div','loading-line'),el('p','loading-copy',title)); return node; }
function retireClerkHost(id, unmount) {
  const host = $(id);
  if (!host) return;
  // Clerk owns this host's children. Its React cleanup can run after unmount
  // returns, so detach the whole host instead of deleting those children.
  // A fresh host also keeps a rapid remount separate from pending old cleanup.
  const replacement = host.cloneNode(false);
  try { if (unmount) unmount(host); } catch (_) {}
  host.replaceWith(replacement);
}
