function teacherAdvice(view) {const node = panel(t('teacherAdvice'),t('teacherAdviceIndex'),'↗');const draft = el('div','recommendation');draft.append(el('p','eyebrow',t('draftLabel')));const recommendation = view.recommendation;const reason = localized(recommendation?.reason);const action = localized(recommendation?.action);if (recommendation) {append(draft,el('h3',null,topicLabel(recommendation.topicId)),el('p',null,reason),el('p',null,action));}else draft.append(el('p',null,t('recommendNoData')));draft.append(el('p','form-note',t('draftReason')));const form = el('form','form-grid');const message = inputField('teacher-advice-message',t('adviceMessage'),{multiline:true,required:true,maxLength:2000,rows:5,placeholder:t('advicePlaceholder')});const counter = el('span','advice-counter','0 / 2000');message.container.append(counter);message.input.addEventListener('input',()=>{counter.textContent = message.input.value.length + ' / 2000';});const focus = inputField('teacher-advice-topic',t('adviceTopic'),{select:[{value:'',label:t('generalAdvice')},...TOPICS.map(topic=>({value:topic,label:t(topic)}))],value:recommendation?.topicId || ''});if (reason || action) draft.append(button(t('useDraft'),'button button-outline button-small',()=>{message.input.value=[reason,action].filter(Boolean).join('\n\n').slice(0,2000);counter.textContent=message.input.value.length+' / 2000';message.input.focus();}));const submit = formButton(t('saveAdvice'));append(form,message.container,focus.container,el('p','form-note',t('adviceShare')),submit);const studentId = view.student.id;form.addEventListener('submit',event=>{event.preventDefault();if(form.reportValidity())void mutate('save-advice',{studentId,message:message.input.value.trim(),focusTopic:focus.input.value || null},form,submit);});append(node,draft,form,append(el('div','section-gap'),el('h3',null,t('sentAdvice'))),append(el('div','section-gap'),adviceCards(view.advice,true)));return node;}
document.querySelectorAll('[data-locale]').forEach(item=>item.addEventListener('click',()=>{const next=item.dataset.locale;if(next===locale)return;locale=next;try{localStorage.setItem('studygps-locale',locale);}catch(_){}const url=new URL(location.href);url.searchParams.set('lang',locale);clearPrivate();unmountSignIn();location.href=url.href;}));
$('auth-retry').addEventListener('click',()=>{unmountSignIn();void bootstrap();});
$('sign-out').addEventListener('click',async()=>{const current=clerk;clearPrivate();userId=null;authState='signedout';unmountSignIn();$('auth-status').textContent=t('authLoading');try{await current?.signOut();$('auth-status').textContent='';mountSignIn();}catch(_){$('auth-status').textContent=t('authFailed');$('auth-retry').hidden=false;}});
$('menu-toggle').addEventListener('click',()=>{const open=$('sidebar').classList.toggle('is-open');$('menu-toggle').setAttribute('aria-expanded',String(open));});
document.addEventListener('click',event=>{if(!event.target.closest('#sidebar')&&!event.target.closest('#menu-toggle')){$('sidebar').classList.remove('is-open');$('menu-toggle').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('sidebar').classList.remove('is-open');$('menu-toggle').setAttribute('aria-expanded','false');}});
